const notes = [
  { id: 1, text: "첫 번째 메모" },
  { id: 2, text: "Next.js 연습하기" },
];

export default function Notes() {
  return (
    <div>
      <p>메모 {notes.length}개</p>
      {notes.map((note) => (
        <article key={note.id}>
          <p>{note.text}</p>
        </article>
      ))}
    </div>
  );
}